import argparse
import json
import logging
import os
import shutil
import sys
from pathlib import Path
from typing import Any, Dict
import time
import hashlib
import random

logger = logging.getLogger(__name__)


def has_docker() -> bool:
    return shutil.which("docker") is not None


def parse_args(argv=None):
    p = argparse.ArgumentParser(description="Minimal social simulation")
    p.add_argument("--input", "-i", default=None, help="Path to input JSON (use '-' for stdin)")
    p.add_argument("--output", "-o", default=None, help="Path to write output JSON (default: stdout)")
    p.add_argument("--steps", type=int, default=10, help="Number of simulation steps")
    p.add_argument("--seed", type=int, default=42, help="Random seed for determinism")
    p.add_argument("--use-docker", action="store_true", help="Attempt to use Docker (guarded; defaults to off)")
    return p.parse_args(argv)


def _format_json_error(e: json.JSONDecodeError, text: str, path: str) -> str:
    # Provide line/col and a snippet for context
    line = e.lineno
    col = e.colno
    start = max(0, e.pos - 40)
    end = min(len(text), e.pos + 40)
    snippet = text[start:end].replace("\n", "\\n")
    return (
        f"Failed to parse JSON in {path or '<stdin>'}: {e.msg} at line {line}, column {col}. "
        f"Context: ...{snippet}..."
    )


def load_json(path: str | None) -> Dict[str, Any]:
    if path is None:
        return {}
    if path == "-":
        text = sys.stdin.read()
        try:
            return json.loads(text)
        except json.JSONDecodeError as e:
            msg = _format_json_error(e, text, "<stdin>")
            logger.error(msg)
            raise SystemExit(3)
    p = Path(path)
    if not p.exists():
        logger.warning("Input file not found: %s; proceeding with empty input", path)
        return {}
    text = p.read_text(encoding="utf-8")
    try:
        return json.loads(text)
    except json.JSONDecodeError as e:
        msg = _format_json_error(e, text, str(p))
        logger.error(msg)
        raise SystemExit(3)


def save_json(obj: Dict[str, Any], path: str | None) -> None:
    out = json.dumps(obj, ensure_ascii=False, indent=2)
    if path:
        Path(path).write_text(out + "\n", encoding="utf-8")
    else:
        sys.stdout.write(out + "\n")


def run_simulation(data: Dict[str, Any], steps: int, seed: int) -> Dict[str, Any]:
    rng = random.Random(seed)
    agents = data.get("agents") or []
    if not isinstance(agents, list):
        agents = []
    agent_count = len(agents)

    # Deterministic toy dynamics: increment a counter per step, plus a small RNG-driven metric
    metrics = {"steps": steps, "agent_count": agent_count, "random_metric": 0.0}
    for _ in range(steps):
        metrics["random_metric"] += rng.random()

    # Input hash for traceability
    input_bytes = json.dumps(data, sort_keys=True).encode("utf-8") if data else b""
    input_hash = hashlib.sha256(input_bytes).hexdigest() if input_bytes else None

    result = {
        "ok": True,
        "seed": seed,
        "timestamp": int(time.time()),
        "summary": metrics,
        "input_hash": input_hash,
    }
    return result


def main(argv=None):
    logging.basicConfig(level=logging.INFO, format="%(levelname)s: %(message)s")
    args = parse_args(argv)

    # Determine Docker usage with guards and env override
    use_docker_requested = bool(args.use_docker)
    skip_docker_env = os.getenv("SIM_SKIP_DOCKER") == "1"
    docker_available = has_docker()
    use_docker = use_docker_requested and not skip_docker_env and docker_available

    if use_docker_requested and not docker_available:
        logger.warning("Docker not found in PATH; falling back to native implementation")
    if skip_docker_env:
        logger.info("SIM_SKIP_DOCKER=1 set; using native implementation")

    # For now, we only run the native path; docker path could be added later
    data = load_json(args.input)

    try:
        result = run_simulation(data, steps=args.steps, seed=args.seed)
    except Exception as exc:
        logger.error("Simulation failed: %s", exc)
        return 1

    try:
        save_json(result, args.output)
    except Exception as exc:
        logger.error("Failed to write output: %s", exc)
        return 1

    logger.info("Simulation completed successfully")
    return 0

# Execute main for both direct execution and sandbox wrapper invocation
ret = main()
# Ensure a deterministic exit status even when imported/executed in sandbox
try:
    code = int(ret) if ret is not None else 0
except Exception:
    code = 1
sys.exit(code)

